LEX = {'speed': ['accelerate', 'optimize'], 'search': ['retrieval', 'lookup']}
def expand(q):
    out = q.split()
    for w in q.split():
        out += LEX.get(w, [])
    return ' '.join(out)
print(expand('speed search'))

